        s.submit("rx", bad)
    except (TypeError, ValueError):
        pass
    else:
        raise AssertionError(("bad now", bad))
# bad request ids
for bad in (1, True, b"x", ""):
    try:
        s.submit(bad, 5)
    except (TypeError, ValueError):
        pass
    else:
        raise AssertionError(("bad id", bad))
assert len(s.pending()) == 2
try:
    s.submit("r7", 2)
except ConnectionStateError:
    pass
else:
    raise AssertionError("regression")

res = s.release_and_dispatch("b", 6)
d = res["dispatched"]
assert d["request_id"] == "r4" and d["backend"] == "b" and d["queued_at"] == 3 and d["expires_at"] == 13
assert [p["request_id"] for p in s.pending()] == ["r5"]
res = s.release_and_dispatch("a", 12)
assert res["dispatched"]["request_id"] == "r5" and res["dispatched"]["backend"] == "a"
res = s.release_and_dispatch("a", 13)
assert res["dispatched"] is None
try:
    s.release_and_dispatch("a", 14)
except ConnectionStateError:
    pass
else:
    raise AssertionError("zero count")
try:
    s.release_and_dispatch("nope", 14)
except KeyError:
    pass
else:
    raise AssertionError
try:
    s.release_and_dispatch(123, 14)
except TypeError:
    pass
else:
    raise AssertionError
try:
    s.release_and_dispatch("b", 12)
except ConnectionStateError:
    pass
else:
    raise AssertionError("regression")
for bad in (-1, True, 1.5):
    try:
        s.release_and_dispatch("b", bad)
    except (TypeError, ValueError):
        pass
    else:
        raise AssertionError(("bad release now", bad))

s2 = QueuedLeastConnectionsScheduler(pool, 3, 5)
s2.submit("q1",0); s2.submit("q2",0); s2.submit("q3",0)
s2.submit("q4",1); s2.submit("q5",2)
res = s2.release_and_dispatch("b", 6)
assert res["dispatched"]["request_id"] == "q5"
assert s2.pending() == []

s3 = QueuedLeastConnectionsScheduler(pool, 5, 10)
